   253  XRef::XRef(BaseStream *strA, Goffset pos, Goffset mainXRefEntriesOffsetA, bool *wasReconstructed, bool reconstruct) : XRef{} {
   254    Object obj;
   255
   256    mainXRefEntriesOffset = mainXRefEntriesOffsetA;
   257
   258    // read the trailer
   259    str = strA;
   260    start = str->getStart();
   261    prevXRefOffset = mainXRefOffset = pos;
   262
   263    if (reconstruct && !(ok = constructXRef(wasReconstructed)))
   264    {
   265      errCode = errDamaged;
   266      return;
   267    }
   268    else
   269    {
   270      // if there was a problem with the 'startxref' position, try to
   271      // reconstruct the xref table
   272      if (prevXRefOffset == 0) {
   273        if (!(ok = constructXRef(wasReconstructed))) {
   274          errCode = errDamaged;
   275          return;
   276        }
   277
   278      // read the xref table
   279      } else {
   280        std::vector<Goffset> followedXRefStm;
   281        readXRef(&prevXRefOffset, &followedXRefStm, nullptr);
   282
   283        // if there was a problem with the xref table,
   284        // try to reconstruct it
   285        if (!ok) {
   286          if (!(ok = constructXRef(wasReconstructed))) {
   287            errCode = errDamaged;
   288            return;
   289          }
   290        }
   291      }
   292
   293      // set size to (at least) the size specified in trailer dict
   294      obj = trailerDict.dictLookupNF("Size");
   295      if (!obj.isInt()) {
   296          error(errSyntaxWarning, -1, "No valid XRef size in trailer");
   297      } else {
   298        if (obj.getInt() > size) {
   299           if (resize(obj.getInt()) != obj.getInt()) {
   300              if (!(ok = constructXRef(wasReconstructed))) {
   301                 errCode = errDamaged;
   302                 return;
   303              }
   304           }
   305        }
   306      }
   307
   308      // get the root dictionary (catalog) object
   309      obj = trailerDict.dictLookupNF("Root");
   310      if (obj.isRef()) {
   311        rootNum = obj.getRefNum();
   312        rootGen = obj.getRefGen();
   313      } else {
   314        if (!(ok = constructXRef(wasReconstructed))) {
   315          errCode = errDamaged;
   316          return;
   317        }
   318      }
   319    }
   320    // now set the trailer dictionary's xref pointer so we can fetch
   321    // indirect objects from it
   322    trailerDict.getDict()->setXRef(this);
   323  }
