   504  bool XRef::readXRefTable(Parser *parser, Goffset *pos, std::vector<Goffset> *followedXRefStm, std::vector<int> *xrefStreamObjsNum) {
   505    XRefEntry entry;
   506    bool more;
   507    Object obj, obj2;
   508    Goffset pos2;
   509    int first, n;
   510
   511    while (1) {
   512      obj = parser->getObj(true);
   513      if (obj.isCmd("trailer")) {
   514        break;
   515      }
   516      if (!obj.isInt()) {
   517        goto err0;
   518      }
   519      first = obj.getInt();
   520      obj = parser->getObj(true);
   521      if (!obj.isInt()) {
   522        goto err0;
   523      }
   524      n = obj.getInt();
   525      if (first < 0 || n < 0 || first > INT_MAX - n) {
   526        goto err0;
   527      }
   528      if (first + n > size) {
   529        if (resize(first + n) != first + n) {
   530          error(errSyntaxError, -1, "Invalid 'obj' parameters'");
   531          goto err0;
   532        }
   533      }
   534      for (int i = first; i < first + n; ++i) {
   535        obj = parser->getObj(true);
   536        if (obj.isInt()) {
   537          entry.offset = obj.getInt();
   538        } else if (obj.isInt64()) {
   539          entry.offset = obj.getInt64();
   540        } else {
   541          goto err0;
   542        }
   543        obj = parser->getObj(true);
   544        if (!obj.isInt()) {
   545          goto err0;
   546        }
   547        entry.gen = obj.getInt();
   548        entry.flags = 0;
   549        obj = parser->getObj(true);
   550        if (obj.isCmd("n")) {
   551          entry.type = xrefEntryUncompressed;
   552        } else if (obj.isCmd("f")) {
   553          entry.type = xrefEntryFree;
   554        } else {
   555          goto err0;
   556        }
   557        if (entries[i].offset == -1) {
   558          entries[i].offset = entry.offset;
   559          entries[i].gen = entry.gen;
   560          entries[i].type = entry.type;
   561          entries[i].flags = entry.flags;
   562          entries[i].obj.setToNull();
   563
   564          // PDF files of patents from the IBM Intellectual Property
   565          // Network have a bug: the xref table claims to start at 1
   566          // instead of 0.
   567          if (i == 1 && first == 1 &&
   568              entries[1].offset == 0 && entries[1].gen == 65535 &&
   569              entries[1].type == xrefEntryFree) {
   570            i = first = 0;
   571            entries[0].offset = 0;
   572            entries[0].gen = 65535;
   573            entries[0].type = xrefEntryFree;
   574            entries[0].flags = entries[1].flags;
   575            entries[0].obj = std::move(entries[1].obj);
   576
   577            entries[1].offset = -1;
   578            entries[1].obj.setToNull();
   579          }
   580        }
