  1456  void XRef::writeStreamToBuffer(GooString *stmBuf, Dict *xrefDict, XRef *xref) {
  1457    Array *index = new Array(xref);
  1458    stmBuf->clear();
  1459
  1460    // First pass: determine whether all offsets fit in 4 bytes or not
  1461    XRefPreScanWriter prescan;
  1462    writeXRef(&prescan, false);
  1463    const int offsetSize = prescan.hasOffsetsBeyond4GB ? sizeof(Goffset) : 4;
  1464
  1465    // Second pass: actually write the xref stream
  1466    XRefStreamWriter writer(index, stmBuf, offsetSize);
  1467    writeXRef(&writer, false);
  1468
  1469    xrefDict->set("Type", Object(objName, "XRef"));
  1470    xrefDict->set("Index", Object(index));
