  1478  bool XRef::parseEntry(Goffset offset, XRefEntry *entry)
  1479  {
  1480    bool r;
  1481
  1482    if (unlikely(entry == nullptr))
  1483      return false;
  1484
  1485    Parser parser(nullptr, new Lexer(nullptr,
  1486       str->makeSubStream(offset, false, 20, Object(objNull))), true);
  1487
  1488    Object obj1, obj2, obj3;
  1489    if (((obj1 = parser.getObj(), obj1.isInt()) || obj1.isInt64()) &&
  1490        (obj2 = parser.getObj(), obj2.isInt()) &&
  1491        (obj3 = parser.getObj(), obj3.isCmd("n") || obj3.isCmd("f"))) {
  1492      if (obj1.isInt64())
  1493        entry->offset = obj1.getInt64();
  1494      else
  1495        entry->offset = obj1.getInt();
  1496      entry->gen = obj2.getInt();
  1497      entry->type = obj3.isCmd("n") ? xrefEntryUncompressed : xrefEntryFree;
  1498      entry->obj.setToNull();
  1499      entry->flags = 0;
  1500      r = true;
  1501    } else {
  1502      r = false;
  1503    }
  1504
  1505    return r;
  1506  }
