  1508  /* Traverse all XRef tables and, if untilEntryNum != -1, stop as soon as
  1509   * untilEntryNum is found, or try to reconstruct the xref table if it's not
  1510   * present in any xref.
  1511   * If xrefStreamObjsNum is not NULL, it is filled with the list of the object
  1512   * numbers of the XRef streams that have been traversed */
  1513  void XRef::readXRefUntil(int untilEntryNum, std::vector<int> *xrefStreamObjsNum)
  1514  {
  1515    std::vector<Goffset> followedPrev;
  1516    while (prevXRefOffset && (untilEntryNum == -1 || (untilEntryNum < size && entries[untilEntryNum].type == xrefEntryNone))) {
  1517      bool followed = false;
  1518      for (size_t j = 0; j < followedPrev.size(); j++) {
  1519        if (followedPrev.at(j) == prevXRefOffset) {
  1520          followed = true;
  1521          break;
  1522        }
  1523      }
  1524      if (followed) {
  1525        error(errSyntaxError, -1, "Circular XRef");
  1526        if (!xRefStream && !(ok = constructXRef(nullptr))) {
  1527          errCode = errDamaged;
  1528        }
  1529        break;
  1530      }
  1531
  1532      followedPrev.push_back (prevXRefOffset);
  1533
  1534      std::vector<Goffset> followedXRefStm;
  1535      if (!readXRef(&prevXRefOffset, &followedXRefStm, xrefStreamObjsNum)) {
  1536          prevXRefOffset = 0;
  1537      }
  1538
  1539      // if there was a problem with the xref table, or we haven't found the entry
  1540      // we were looking for, try to reconstruct the xref
  1541      if (!ok || (!prevXRefOffset && untilEntryNum != -1 && entries[untilEntryNum].type == xrefEntryNone)) {
  1542          if (!xRefStream && !(ok = constructXRef(nullptr))) {
  1543              errCode = errDamaged;
  1544              break;
  1545          }
  1546          break;
  1547      }
  1548    }
